package grading.similarity;

import java.util.ArrayList;
import java.util.List;

/**
 * Greedy String Tiling (Wise, 1993), the method behind JPlag. It repeatedly finds the longest runs
 * of identical tokens not yet covered in both sequences and covers them with "tiles", down to a
 * minimum run length. Because tiles are found in any order, copied methods that were moved around
 * are still matched. Similarity is the share of both sequences covered by tiles. It is exact but
 * slower than winnowing (cubic in the worst case), so it is only run on pairs winnowing picked out.
 */
final class GreedyStringTiling implements SimilarityAlgorithm {

    private final int minMatchLength;

    GreedyStringTiling(int minMatchLength) {
        this.minMatchLength = minMatchLength;
    }

    @Override
    public String name() {
        return "Greedy String Tiling (minimum match " + minMatchLength + " tokens)";
    }

    @Override
    public Comparison compare(List<Token> first, List<Token> second) {
        if (first.isEmpty() || second.isEmpty()) {
            return Comparison.none();
        }
        String[] firstKinds = first.stream().map(Token::kind).toArray(String[]::new);
        String[] secondKinds = second.stream().map(Token::kind).toArray(String[]::new);
        boolean[] coveredFirst = new boolean[firstKinds.length];
        boolean[] coveredSecond = new boolean[secondKinds.length];
        List<Comparison.Match> tiles = new ArrayList<>();
        int longest = minMatchLength;
        do {
            longest = minMatchLength;
            List<Comparison.Match> candidates = new ArrayList<>();
            for (int i = 0; i < firstKinds.length; i++) {
                for (int j = 0; j < secondKinds.length; j++) {
                    int length = 0;
                    while (i + length < firstKinds.length && j + length < secondKinds.length
                            && !coveredFirst[i + length] && !coveredSecond[j + length]
                            && firstKinds[i + length].equals(secondKinds[j + length])) {
                        length++;
                    }
                    if (length > longest) {
                        candidates.clear();
                        longest = length;
                    }
                    if (length == longest) {
                        candidates.add(new Comparison.Match(i, j, length));
                    }
                }
            }
            for (Comparison.Match candidate : candidates) {
                if (uncovered(coveredFirst, candidate.first(), candidate.length())
                        && uncovered(coveredSecond, candidate.second(), candidate.length())) {
                    cover(coveredFirst, candidate.first(), candidate.length());
                    cover(coveredSecond, candidate.second(), candidate.length());
                    tiles.add(candidate);
                }
            }
        } while (longest > minMatchLength);
        int covered = tiles.stream().mapToInt(Comparison.Match::length).sum();
        return new Comparison(2.0 * covered / (firstKinds.length + secondKinds.length), tiles);
    }

    private static boolean uncovered(boolean[] covered, int start, int length) {
        for (int index = start; index < start + length; index++) {
            if (covered[index]) {
                return false;
            }
        }
        return true;
    }

    private static void cover(boolean[] covered, int start, int length) {
        for (int index = start; index < start + length; index++) {
            covered[index] = true;
        }
    }
}
